1	// Query-string rewriting for matched routes: queryTransforms are applied
2	// after route selection and never touch path matching or joining. The
3	// rewriter works on raw fragments so unmodified parameters (including
4	// duplicates, empty values and empty fragments) keep their original bytes
5	// and relative order; only a rule's target parameter is decoded for name
6	// comparison and re-encoded when set.
7	package contractsentinel
8	
9	import "strings"
10	
11	// queryItem is one '&'-separated fragment of a query string in its current
12	// order. Empty fragments ("" between separators) are retained but never
13	// match a parameter name.
14	type queryItem struct {
15		empty bool   // an empty fragment, kept verbatim but not a parameter
16		name  string // decoded parameter name (only meaningful when !empty)
17		raw   string // original fragment text, or the encoded pair after a set
18	}
19	
20	// applyQueryTransforms parses the raw query of target (the text after the
21	// first '?') and applies the route's transforms in array order. It returns
22	// the full query suffix including a leading '?', or "" when the final
23	// result has no query string.
24	func applyQueryTransforms(transforms []*QueryTransform, target string) (string, *Failure) {
25		i := strings.IndexByte(target, '?')
26		if len(transforms) == 0 {
27			// No rules: the original query is preserved byte for byte.
28			if i < 0 {
29				return "", nil
30			}
31			return target[i:], nil
32		}
33	
34		var items []queryItem
35		present := false
36		if i >= 0 {
37			present = true
38			raw := target[i+1:]
39			// An empty query string ("?") has no fragments at all; every other
40			// empty fragment (e.g. from "?&" or "?a=1&") is retained as such.
41			if raw != "" {
42				for _, frag := range strings.Split(raw, "&") {
43					if frag == "" {
44						items = append(items, queryItem{empty: true})
45						continue
46					}
47					namePart := frag
48					if j := strings.IndexByte(frag, '='); j >= 0 {
49						namePart = frag[:j] // the first '=' splits name and value
50					}
51					name, ok := decodeQueryName(namePart)
52					if !ok {
53						// ParseRequest validates the whole target, so this is a
54						// belt-and-braces guard.
55						return "", failuref("invalid_request", "target contains an invalid percent escape")
56					}
57					items = append(items, queryItem{name: name, raw: frag})
58				}
59			}
60		}
61	
62		for _, tr := range transforms {
63			switch tr.Op {
64			case "remove":
65				present, items = applyRemove(items, present, tr.Name)
66			case "set":
67				present, items = applySet(items, present, tr.Name, tr.Value)
68			case "rename":
69				items = applyRename(items, tr.Name, tr.To)
70			}
71		}
72	
73		if !present {
74			return "", nil
75		}
76		parts := make([]string, len(items))
77		for k, it := range items {
78			parts[k] = it.raw
79		}
80		return "?" + strings.Join(parts, "&"), nil
81	}
82	
83	// matchesName is the one shared parameter-matching rule: an item is a hit
84	// when it is a parameter (not an empty fragment) whose decoded name equals
85	// name. Name decoding itself happens once at parse time, so every op compares
86	// the same decoded, case-sensitive form.
87	func matchesName(it queryItem, name string) bool {
88		return !it.empty && it.name == name
89	}
90	
91	// firstNameHit returns the index of the first parameter matching name, or -1
92	// when no parameter carries that name.
93	func firstNameHit(items []queryItem, name string) int {
94		for k := range items {
95			if matchesName(items[k], name) {
96				return k
97			}
98		}
99		return -1
100	}
101	
102	// dropName is the one shared keep-the-rest rule: it compacts items in place,
103	// removing every parameter matching name while empty fragments and all other
104	// parameters keep their relative order and original bytes.
105	func dropName(items []queryItem, name string) []queryItem {
106		kept := items[:0]
107		for _, it := range items {
108			if !matchesName(it, name) {
109				kept = append(kept, it)
110			}
111		}
112		return kept
113	}
114	
115	// applyRemove deletes every parameter whose decoded name equals name. With
116	// no hit the query is untouched; after a hit the '?' is dropped only when no
117	// parameters or empty fragments remain.
118	func applyRemove(items []queryItem, present bool, name string) (bool, []queryItem) {
119		if firstNameHit(items, name) < 0 {
120			return present, items
121		}
122		kept := dropName(items, name)
123		if len(kept) == 0 {
124			return false, kept
125		}
126		return true, kept
127	}
128	
129	// applySet merges all parameters with the decoded name into one encoded
130	// name=value pair at the first hit's position; a name that is absent is
131	// appended to the end and creates a query string when none existed.
132	func applySet(items []queryItem, present bool, name, value string) (bool, []queryItem) {
133		encoded := encodeQueryComponent(name) + "=" + encodeQueryComponent(value)
134		first := firstNameHit(items, name)
135		if first < 0 {
136			items = append(items, queryItem{name: name, raw: encoded})
137			return true, items
138		}
139		// The merged pair takes the first hit's place; every later duplicate is
140		// dropped by the same keep-the-rest rule remove uses.
141		items[first].raw = encoded
142		return true, append(items[:first+1], dropName(items[first+1:], name)...)
143	}
144	
145	// applyRename renames in place every parameter whose decoded name equals
146	// name: its name is re-encoded as to while the '=' (if any) and the raw
147	// value bytes after it are kept verbatim. Parameters already named to,
148	// empty fragments and non-matching parameters are untouched; when nothing
149	// matches (or name and to are identical) every fragment keeps its bytes.
150	func applyRename(items []queryItem, name, to string) []queryItem {
151		if name == to {
152			// Renaming to the same name must not re-encode existing names.
153			return items
154		}
155		encodedTo := encodeQueryComponent(to)
156		for k := range items {
157			if !matchesName(items[k], name) {
158				continue
159			}
160			frag := items[k].raw
161			if j := strings.IndexByte(frag, '='); j >= 0 {
162				// Keep the '=' and everything after it byte for byte.
163				frag = encodedTo + frag[j:]
164			} else {
165				frag = encodedTo
166			}
167			items[k].raw = frag
168			items[k].name = to
169		}
170		return items
171	}
172	
173	// decodeQueryName percent-decodes a raw parameter name with '+' treated as a
174	// space, as application/x-www-form-urlencoded does. Matching is
175	// case-sensitive and applies no other normalization. The bool reports
176	// whether every percent escape was well-formed.
177	func decodeQueryName(s string) (string, bool) {
178		var b strings.Builder
179		for i := 0; i < len(s); i++ {
180			switch s[i] {
181			case '+':
182				b.WriteByte(' ')
183			case '%':
184				if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
185					return "", false
186				}
187				b.WriteByte(unhex(s[i+1])<<4 | unhex(s[i+2]))
188				i += 2
189			default:
190				b.WriteByte(s[i])
191			}
192		}
193		return b.String(), true
194	}
195	
196	// encodeQueryComponent renders a literal name or value as query text: ASCII
197	// letters, digits and -._~ stay as-is, every other byte (including spaces
198	// and the individual bytes of multi-byte UTF-8 sequences) becomes an
199	// uppercase percent escape.
200	func encodeQueryComponent(s string) string {
201		var b strings.Builder
202		for i := 0; i < len(s); i++ {
203			c := s[i]
204			if isUnreserved(c) {
205				b.WriteByte(c)
206			} else {
207				b.WriteByte('%')
208				b.WriteByte(hexDigit(c >> 4))
209				b.WriteByte(hexDigit(c & 0x0f))
210			}
211		}
212		return b.String()
213	}
214	
215	func isUnreserved(c byte) bool {
216		switch {
217		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
218			return true
219		}
220		switch c {
221		case '-', '.', '_', '~':
222			return true
223		}
224		return false
225	}
226	
227	func unhex(c byte) byte {
228		switch {
229		case c >= '0' && c <= '9':
230			return c - '0'
231		case c >= 'a' && c <= 'f':
232			return c - 'a' + 10
233		default:
234			return c - 'A' + 10
235		}
236	}
237	
238	func hexDigit(n byte) byte {
239		const digits = "0123456789ABCDEF"
240		return digits[n]
241	}
