	cfg := transformConfig(t, `[{"op":"remove","name":"a&b=c"}]`)
	for _, target := range []string{
		"/p?a%26b%3dc=%zz&keep=1",
		"/p?a%26b%3dc=1%2",
	} {
		res, rf := Resolve(cfg, &Request{Method: "GET", Target: target})
		t.Logf("Resolve(%q): res=%+v rf=%+v", target, res, rf)
	}
}
